                a and a.pop(0); continue
            if x.startswith('-'):
                continue
            sub = x; break
        if sub == 'worktree' and a and a[0] == 'list':
            return 'git-other'
        if sub == 'stash' and a and a[0] in ('list', 'show'):
            return 'git-other'
